package com.answerbase.core.documents;

import java.io.IOException;

/** Private originals; keys are generated by the server, never accepted from a client. */
public interface DocumentStorage {
    void put(String key, byte[] bytes, String contentType) throws IOException;

    byte[] get(String key) throws IOException;

    void delete(String key) throws IOException;

    default java.util.List<String> staleKeys(java.time.Duration age) throws IOException {
        return java.util.List.of();
    }

    int MAX_BYTES = 5 * 1024 * 1024;
}
